CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS tenants (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(255) UNIQUE NOT NULL, domains JSONB DEFAULT '[]', status VARCHAR(20) DEFAULT 'active', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID REFERENCES tenants(id), name VARCHAR(255) DEFAULT '', email VARCHAR(255) NOT NULL, password VARCHAR(255) NOT NULL, roles JSONB DEFAULT '[]', portals JSONB DEFAULT '[]', is_active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(tenant_id, email));
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID REFERENCES tenants(id) NOT NULL, sku VARCHAR(100) NOT NULL, name VARCHAR(255) NOT NULL, category VARCHAR(100), is_active BOOLEAN DEFAULT true, reorder_threshold INTEGER DEFAULT 10, cost_per_unit DECIMAL(10,2), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(tenant_id, sku));
CREATE TABLE IF NOT EXISTS inventory (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), product_id UUID REFERENCES products(id) UNIQUE NOT NULL, tenant_id UUID REFERENCES tenants(id) NOT NULL, current_inventory INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID REFERENCES tenants(id) NOT NULL, product_id UUID REFERENCES products(id) NOT NULL, quantity INTEGER NOT NULL, status VARCHAR(20) DEFAULT 'created', approved_by UUID REFERENCES users(id), approved_at TIMESTAMPTZ, cancelled_by UUID REFERENCES users(id), cancelled_at TIMESTAMPTZ, cancel_reason TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
